#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    //Variables generated by computer. Do not re-declare
    double usage = 30;
    char type = 'D';

    //type in your answer in the answer box for code within this section only
    string category;
double waterCharge, sewerage, total = 0.0;
 
switch(type) {
    case 'D': {
        if (usage<0) {
            cout << "Invalid input." << endl;
        } else {
            if (usage <= 20 && usage > 0) {
                waterCharge = usage* 0.57;
            }
            else if (usage <= 35 && usage > 20) {
                waterCharge = 0.57*20 + (usage-20)* 1.03;
            }  
            else if (usage > 35) {
                waterCharge = 0.57*20 + 1.03*15 + (usage-35)*2.00; 
            }
            if (waterCharge < 6.00) waterCharge=6.00;
            category = "Domestic";
            sewerage = 8.00;
            total = sewerage + waterCharge;
            break;
        }
    }   
    case 'C': {
        if (usage<0) {
            cout << "Invalid input." << endl;
        } else {
            if (usage<=35) {
                waterCharge = usage*2.07;
            }
            else {
                waterCharge = 35*2.07 + (usage-35)*2.28; 
            }
            if (waterCharge < 36.00) waterCharge = 36.00;
            category = "Commercial";
            sewerage = 0.1*waterCharge;
            total = sewerage + waterCharge;
            break;
        }        
    }
    default: {
        cout << "Invalid input." << endl;
        break;
    }
}

cout << left <<  setw(15) << "Category" << ": " << category << endl;
cout << left <<  setw(15) <<"Water charge"  << ": " << "RM " << fixed << setprecision(2) << waterCharge << endl;
cout << left <<  setw(15) <<"Sewerage" <<  ": " << "RM " << fixed << setprecision(2) <<  sewerage << endl;
cout << left <<  setw(15) <<"Total" << ": " << "RM " << fixed << setprecision(2) <<  total << endl;


    return 0;
}
